import{_ as t,o,c as a,a2 as r}from"./chunks/framework.BS0bAV7E.js";const p=JSON.parse('{"title":"Portability notes for contributors","description":"","frontmatter":{},"headers":[],"relativePath":"dev/portability.md","filePath":"dev/portability.md"}'),s={name:"dev/portability.md"};function n(i,e,c,l,d,u){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="portability-notes-for-contributors" tabindex="-1">Portability notes for contributors <a class="header-anchor" href="#portability-notes-for-contributors" aria-label="Permalink to &quot;Portability notes for contributors&quot;">​</a></h1><p>The tree builds on GCC 14.x locally and on newer toolchains on CI. Three classes of difference have already bitten - keep them in mind:</p><h2 id="_1-stricter-warning-classes-on-newer-gcc" tabindex="-1">1. Stricter warning classes on newer GCC <a class="header-anchor" href="#_1-stricter-warning-classes-on-newer-gcc" aria-label="Permalink to &quot;1. Stricter warning classes on newer GCC&quot;">​</a></h2><p><code>-Waddress-of-packed-member</code> (part of <code>-Wall</code> since GCC 9, enforced harder on newer releases): casting a packed-struct pointer to a naturally-aligned type is an error under <code>-Werror</code>. The multiboot2 tag types are ALL declared <code>__attribute__((packed))</code> for exactly this reason - including the mmap tag (4x u32, no layout change) and the BASIC_MEMINFO reader which goes through a packed tag type instead of a bare <code>u32*</code> cast.</p><p>Rule: when you cast a pointer that came from packed memory, target a packed type.</p><h2 id="_2-stricter-assemblers-binutils-gas" tabindex="-1">2. Stricter assemblers (binutils/GAS) <a class="header-anchor" href="#_2-stricter-assemblers-binutils-gas" aria-label="Permalink to &quot;2. Stricter assemblers (binutils/GAS)&quot;">​</a></h2><p><code>setcc</code>/<code>setc</code> accept BYTE registers only. The rdrand wrapper declared its flag as <code>u32</code> with an <code>&quot;=q&quot;</code> constraint - older GAS silently truncated to the byte subregister, newer GAS rejects the operand size. It is <code>u8</code> now.</p><p>Rule: setcc-style flags are <code>u8</code>, constraint <code>&quot;=q&quot;</code>.</p><h2 id="_3-toolchain-layout-assumptions" tabindex="-1">3. Toolchain layout assumptions <a class="header-anchor" href="#_3-toolchain-layout-assumptions" aria-label="Permalink to &quot;3. Toolchain layout assumptions&quot;">​</a></h2><p><code>OC_TOOLS</code> may point at a relocatable tree (<code>&lt;root&gt;/usr/{bin,lib}</code>) OR a system root (<code>/usr</code> with <code>{bin,lib}</code> directly under it). The embed_grub generator probes both layouts - do not assume either one.</p><h2 id="compile-flag-contract" tabindex="-1">Compile-flag contract <a class="header-anchor" href="#compile-flag-contract" aria-label="Permalink to &quot;Compile-flag contract&quot;">​</a></h2><p>The kernel flags are fixed in the Makefile: <code>-ffreestanding -fno-stack-protector -fno-pie -fno-pic -mno-red-zone -mno-sse -mno-mmx -mno-3dnow -mcmodel=kernel -fno-asynchronous-unwind-tables -Wall -Wextra -Werror -O2 -g -std=gnu11</code>. New flags belong in the Makefile (one place), not scattered in files.</p><h2 id="cross-builds" tabindex="-1">Cross builds <a class="header-anchor" href="#cross-builds" aria-label="Permalink to &quot;Cross builds&quot;">​</a></h2><p><code>make ARCH=arm64</code> / <code>ARCH=riscv</code> use the aarch64/riscv64 cross toolchains and their own linker rules (<code>--hash-style=sysv --build-id=none</code>; <code>-n</code> and PHDR layouts do not mix). The bring-up shells are real (PL011/NS16550A divisors, timer counters, heartbeat) but deliberately minimal - x86_64 is the feature-complete architecture.</p>',14)])])}const b=t(s,[["render",n]]);export{p as __pageData,b as default};
